link.script:
function updateFavicon() {
    const darkMode = window.matchMedia("(prefers-color-scheme: dark)").matches;
    if (darkMode) {
        document.getElementById("favicon-cc").href = "https://tweaki.exportersmm.com/assets/media/logo/6.png";
    } else {
        document.getElementById("favicon-cc").href = "https://tweaki.exportersmm.com/assets/media/logo/7.png";
    }
}

updateFavicon(); // Run on page load
window.matchMedia("(prefers-color-scheme: dark)").addEventListener("change", updateFavicon);

body.script:
const defaultThemeMode = 'light';
     let themeMode;

     if ( document.documentElement ) {
         if ( localStorage.getItem('theme')) {
                 themeMode = localStorage.getItem('theme');
         } else if ( document.documentElement.hasAttribute('data-theme-mode')) {
             themeMode = document.documentElement.getAttribute('data-theme-mode');
         } else {
             themeMode = defaultThemeMode;
         }

         if (themeMode === 'system') {
             themeMode = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
         }

         document.documentElement.classList.add(themeMode);
     }
